function UIActivityPtMainOpenPageNode:Awake()
	CfUtils.SetActive(self.ActivityPtCutsceneDialog, false)
	
	SetButtonAction(self.BtnDesc, Bind(self, self.OnBtnDesc))
	SetButtonAction(self.BtnGroup1, Bind(self, self.OnBtnShop))
	SetButtonAction(self.BtnGroup2, Bind(self, self.OnBtnPlot))
	SetButtonAction(self.BtnGroup3, Bind(self, self.OnBtnTask))
	SetButtonAction(self.BtnGo, Bind(self, self.OnBtnGo))
	
	CfUtils.SetTopCommonCb(function ()
		if self._isPlot then
			self:PlayEntryAni()
			local dialog = UIModule.CurrentScreen:LastDialog()
			dialog:SetSortOrder(0)
			self._isPlot = false
		else
			local CriWareUtils    = import('Game.Entry.CriWareUtilsFix')
			---@type PlayerComponent
			local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
			local musicId = playerComponent:GetCurrentMusicId()
			if musicId then
				---@type MusicPlayerVo
				local musicVo = CfUtils.GetCfVo(AutoIds.IdSetting899, "MusicPlayerVo", musicId)
				if musicVo then
					CriWareUtils.PlayMusicById(musicVo.musicId)
				end
			else
				CriWareUtils.PlayRandomBGMFromCDList()
			end
			
			UIModule.BackDialog()
		end
	end)
end

function UIActivityPtMainOpenPageNode:Refresh(activityUuid)
	self._curUuid = checkNumber(activityUuid)
	
	self:InitData()
	if not self._vo then
		return
	end
	
	self._co = cs_coroutine.start(function ()
		local isEntry = KCookie.Get("UIActivityPtNodeEntry")
		CfUtils.SetActive(self.ActivityPtCutsceneDialog, checkNumber(isEntry) == 1)
		CfUtils.SetActive(self.Root, not (checkNumber(isEntry) == 1))
		CfUtils.SetActive(self.BgGroup, not (checkNumber(isEntry) == 1))
		if checkNumber(isEntry) == 1 then
			local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
			CriWareUtils.PlayMusicById(self._vo.openSound)
			cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.833))
			CfUtils.SetActive(self.BgGroup, true)
			CfUtils.SetActive(self.Root, true)
			CfUtils.SetActive(self.ActivityPtCutsceneDialog, false)
			self:FillMainPanel()
		else
			self:FillMainPanel()
		end
		
		self:PlayEntryAni()
	end)
	local indexId = checkInt(CfUtils.GetLocalData("UIActivityPtPlot", 0))
	local currentIndex = self:GetMaxPlotId()
	if currentIndex  > indexId then
		GameUtils.SetRedPointNum(Constants.RedPointConst.MainActivityPTStory ,1 )
	else
		GameUtils.SetRedPointNum(Constants.RedPointConst.MainActivityPTStory ,0 )
	end
	GameUtils.BindRedPoint(Constants.RedPointConst.MainActivityPTStory, self.BtnGroup2, true)
	GameUtils.BindRedPoint(Constants.RedPointConst.MainActivityPTTask, self.BtnGroup3, true)
end

function UIActivityPtMainOpenPageNode:GetMaxPlotId()
	local currentIndex = 0;
	for k, v in pairs(self._allPlots) do
		local isUnlock = ActivityPtUtils.IsUnlockQuest(v)
		if isUnlock and checkInt(v) >= currentIndex then
			currentIndex = checkInt(v)
		end
	end
	return currentIndex
end

function UIActivityPtMainOpenPageNode:FillCharacterStoryPanel()
	local name = "ActivityPtMainStory_Change_Entry"
	CfUtils.PlayAnimation(self.controller.gameObject, name)
	local index = self:GetMaxPlotId()
	CfUtils.WriteLocalData("UIActivityPtPlot" , index)
	GameUtils.SetRedPointNum(Constants.RedPointConst.MainActivityPTStory ,0 )
	GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.MainActivityPTStory)
	self:FillPlots()
end

function UIActivityPtMainOpenPageNode:FillPlots()
	if not self.LeftTabItem.IsListViewInit then
		self.LeftTabItem:InitListView(#self._allPlots, Bind(self, self.OnGetItemByIndex))
	else
		GameUtils.ReloadData(self.LeftTabItem, #self._allPlots)
	end
	
	self:FillPlotInfo()
end

function UIActivityPtMainOpenPageNode:OnGetItemByIndex(listView, index)
	if index < 0 then
		return nil
	end
	local cell = listView:NewListViewItem("Cell")
	local go = cell.gameObject
	
	local data = ActivityPtUtils.GetActivityPtPlotVo(self._allPlots[index + 1])
	self:FillPlot(go, data)
	
	return cell
end

function UIActivityPtMainOpenPageNode:FillPlot(go, data)
	if not go or not data then
		return
	end
	local animRootGo = go.transform:Find("AnimRoot")
	local isSelect = checkNumber(data.id) == checkNumber(self._curSelectId)
	local isUnlock = ActivityPtUtils.IsUnlockQuest(data.id)
	local isPass = ActivityPtUtils.IsPassQuest(data.id)
	CfUtils.SetActive(animRootGo.transform:Find("ImgFinish"), isPass)
	--CfUtils.SetActive(animRootGo.transform:Find("ImgIcon"), not isPass)
	if not isPass then
		local status = isUnlock and 1 or 2
		if isSelect then
			status = isUnlock and 3 or 4
		end
		CfUtils.SetUISwitchImage(animRootGo.transform:Find("ImgIcon"), status)
	else
		local status = isSelect and 3 or 1
		CfUtils.SetUISwitchImage(animRootGo.transform:Find("ImgIcon"), status)
	end
	CfUtils.FillText(animRootGo.transform:Find("TxtName"), data.name)
	
	CfUtils.PlayAnimation(animRootGo, isSelect and "ActivityPtMainCharacterStoryPanel_select" or "ActivityPtMainCharacterStoryPanel_defualt")
	SetButtonAction(go, Bind(self, self.OnBtnSelectPlot, data.id))
end

function UIActivityPtMainOpenPageNode:OnBtnSelectPlot(id)
	if checkNumber(id) == 0 then
		return
	end
	if checkNumber(self._curSelectId) == checkNumber(id) then
		return
	end
	local ind = table.indexof(self._allPlots, checkString(self._curSelectId))
	if ind then
		local go = self.LeftTabItem:GetShownItemByItemIndex(ind - 1)
		if go then
			local animRootGo = go.transform:Find("AnimRoot")
			CfUtils.PlayAnimation(animRootGo, "ActivityPtMainCharacterStoryPanel_defualt")
			local isPass = ActivityPtUtils.IsPassQuest(self._curSelectId)
			local isUnlock = ActivityPtUtils.IsUnlockQuest(self._curSelectId)
			if not isPass then
				local status = isUnlock and 1 or 2
				CfUtils.SetUISwitchImage(animRootGo.transform:Find("ImgIcon"), status)
			else
				CfUtils.SetUISwitchImage(animRootGo.transform:Find("ImgIcon"), 1)
			end
		end
	end
	
	self._curSelectId = checkString(id)
	ind = table.indexof(self._allPlots, checkString(self._curSelectId))
	if ind then
		local go = self.LeftTabItem:GetShownItemByItemIndex(ind - 1)
		if go then
			local animRootGo = go.transform:Find("AnimRoot")
			CfUtils.PlayAnimation(animRootGo, "ActivityPtMainCharacterStoryPanel_select")
			local isPass = ActivityPtUtils.IsPassQuest(self._curSelectId)
			local isUnlock = ActivityPtUtils.IsUnlockQuest(self._curSelectId)
			if not isPass then
				local status = isUnlock and 3 or 4
				CfUtils.SetUISwitchImage(animRootGo.transform:Find("ImgIcon"), status)
			else
				local status = isUnlock and 3 or 1
				CfUtils.SetUISwitchImage(animRootGo.transform:Find("ImgIcon"), status)
			end
		end
	end
	CfUtils.PlayAnimation(self.controller.gameObject, "ActivityPtMainStory_Change_Select")
	self:FillPlotInfo()
end

function UIActivityPtMainOpenPageNode:FillPlotInfo()
	local vo = ActivityPtUtils.GetActivityPtPlotVo(self._curSelectId)
	if not vo then
		return
	end
	
	CfUtils.FillText(self.TxtName, vo.chapter)
	local isUnlock = ActivityPtUtils.IsUnlockQuest(self._curSelectId)
	local isPass = ActivityPtUtils.IsPassQuest(self._curSelectId)
	
	CfUtils.SetActive(self.TxtOutline, isUnlock)
	CfUtils.SetActive(self.TxtCondition, not isUnlock)
	if isUnlock then
		CfUtils.FillText(self.TxtOutline, vo.desc)
	else
		local unlockNum = checkInt(vo.unlockPropNum)
		local needNum  = checkInt(ActivityPtComponent:GetGetActivityGoodsNum())
		if unlockNum >= needNum then
			CfUtils.FillText(self.TxtCondition, string.fmt("<color=#_color_>_num1_</color><color=#FFFFFF>/_num2_</color>", {_color_ = self._vo.characterColour,  _num1_ = ActivityPtComponent:GetGetActivityGoodsNum(), _num2_ = vo.unlockPropNum}) )
		else
			CfUtils.FillText(self.TxtCondition, string.fmt("<color=#FFFFFF>_num1_/_num2_</color>", {_num1_ = ActivityPtComponent:GetGetActivityGoodsNum(), _num2_ = vo.unlockPropNum}) )
		end
	end
	
	CfUtils.RefeshGoodGo2(self.GoodNode, vo.rewardId, "x"..vo.rewardNum, nil, nil, function()
		local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.rewardId)
		GameUtils.ShowCommonTipsBoard(self.GoodNode, vo.name, vo.desc, vo.quality, vo.id)
	end)
	local scr = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
	if scr then
		scr:SetSanXingGainShow(isPass)
	end
	
	CfUtils.SetActive(self.UIFX_FlowerGlow, isUnlock)
	CfUtils.SetActive(self.TxtState, isUnlock)
	CfUtils.SetActive(self.ImgLock, not isUnlock)
	CfUtils.SetUISwitchImage(self.ImgStory, isUnlock and 2 or 1)
	CfUtils.SetUISwitchText(self.Text, isUnlock and 1 or 2)
	
	local status = isUnlock and 1 or 2
	status = isPass and 2 or status
	CfUtils.SetUISwitchText(self.TxtState, status)
end

function UIActivityPtMainOpenPageNode:PlayEntryAni()
	local name = ""
	local isEntry = KCookie.Get("UIActivityPtNodeEntry")
	if checkNumber(isEntry) == 1 then
		name = "ActivityPtMain_go"
		KCookie.Set("UIActivityPtNodeEntry", 0)
	elseif self._isPlot then
		name = "ActivityPtMainStory_Change_Back"
	else
		name = "ActivityPtMainSubpages_Change_Entry"
	end
	
	CfUtils.PlayAnimation(self.controller.gameObject, name)
end

function UIActivityPtMainOpenPageNode:InitData()
	local t = ActivityPtComponent:GetActivityConf()
	self._vo = ActivityPtUtils.GetActivityPtPlanVo(t.id)
	self._allPlots = ActivityPtUtils.GetAllPlotIds(t.id)
	if checkNumber(self._curSelectId) == 0 then
		self._curSelectId= self._allPlots[1]
	end
end

function UIActivityPtMainOpenPageNode:FillMainPanel()
	self:FillTime()
	self:FillRoleInfo()
end

---FillRoleInfoItem
---@param vo CardVo
function UIActivityPtMainOpenPageNode:FillRoleInfoItem(vo)
	if not vo then
		return
	end
	CfUtils.FillText(self.TxtName1, vo.name)
	CfUtils.FillText(self.TxtName3, vo.descr)
	CfUtils.FillImage(self.ImgType, CardUtils.GetCardRaceIconPath(vo.race))
end

function UIActivityPtMainOpenPageNode:FillRoleInfo()
	self.cardIds = string.split(self._vo.cardId, ";")
	local count = #self.cardIds
	self.preIndex = self:GetPreSelectIndex()
	if not self.LoopListRoleHead.IsListViewInit then
		self.LoopListRoleHead:InitListView(count, Bind(self, self.OnRefreshCellIndex))
	else
		GameUtils.ReloadData(self.LoopListRoleHead, count)
	end
	
	self:OnBtnRoleHeadClick(self.preIndex)
end

function UIActivityPtMainOpenPageNode:GetPreSelectIndex()
	local index = CfUtils.GetLocalData(self:GetLocalKey(),1)
	return checkNumber(index)
end

function UIActivityPtMainOpenPageNode:GetLocalKey()
	return string.format("UIActivityPtMainOpenPageNode_Select_Head_%s",ActivityPtComponent:GetActivityConf().id)
end

function UIActivityPtMainOpenPageNode:OnRefreshCellIndex(listView, index)
	if index < 0 or index >= #self.cardIds then
		return
	end
	local cell = listView:NewListViewItem(ItemCell)
	local tableCellEnv = CfUtils.GetLuaScr(cell, RoleHeadCell)
	if tableCellEnv then
		tableCellEnv:SetCallBack(Bind(self,self.OnBtnRoleHeadClick))
		local id = string.format("%s_%s",self.cardIds[index + 1], ActivityPtComponent:GetActivityConf().id)
		tableCellEnv:RefreshCell(id, index + 1, self.preIndex)
	end
	return cell
end

function UIActivityPtMainOpenPageNode:OnBtnRoleHeadClick(index)
	if isNotNull(self.selectIndex) and self.selectIndex == index then
		return
	end
	
	if isNotNull(self.selectIndex) then
		local cardId = self.cardIds[self.selectIndex]
		self:SetRoleHeadSelectState(self.selectIndex,false)
		if self.spineNode[cardId] then
			CfUtils.SetActive(self.spineNode[cardId].gameObject, false)
		end
	end
	self.selectIndex = index
	CfUtils.WriteLocalData(self:GetLocalKey(),self.selectIndex)
	local cardId = self.cardIds[self.selectIndex]
	local vo = CardConfMgr:GetInstance():GetCardByRefId(cardId)
	if isNotNull(vo) then
		self:FillRoleInfoItem(vo, true)
	end
	
	if isNull(self.spineNode[cardId]) then
		local spinePathId = string.format("%s_%s",cardId, ActivityPtComponent:GetActivityConf().id)
		local vo = CfUtils.GetCfVo(AutoIds.IdSetting6728,"ActivityPtSpinePathVo",spinePathId)
		if isNotNull(vo) and isNotNull(vo.node) then
			ResourceModule.LoadBundleAsync(vo.node, function(_loader, isOk, resultObject)
				if isOk then
					local spineGo = _loader:Instantiate()
					KTool.SetParent(spineGo, self.RoleNode.gameObject,false)
					self.spineNode[cardId] = spineGo
					CfUtils.SetActive(self.spineNode[cardId].gameObject, true)
				end
			end)
		end
	else
		CfUtils.SetActive(self.spineNode[cardId].gameObject, true)
	end
end

function UIActivityPtMainOpenPageNode:SetRoleHeadSelectState(index, state)
	local item = self.LoopListRoleHead:GetShownItemByItemIndex(index - 1)
	if isNotNull(item) then
		local env = CfUtils.GetLuaScr(item, RoleHeadCell)
		if env then
			env:SetSelectState(state)
		end
	end
end

function UIActivityPtMainOpenPageNode:FillTime()
	local data = ActivityPtUtils.GetActivityData(self._curUuid)
	if not data then
		return
	end
	
	local startTime = data.startTime
	local closeTime = data.closeTime
	local endTime = data.endTime
	CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(startTime, endTime))
end

